<script setup lang="ts">
import {ref,computed,watch,onMounted,onBeforeUnmount} from 'vue';import {api} from '../api';import type {WorkTab} from '../stores';import Modal from '../components/Modal.vue';
const props=defineProps<{tab:WorkTab;embedded?:boolean}>();
const empty=()=>({employee_code:'',employee_name:'',store_id:props.tab.store,movement_type:'onboarding',onboarding_is_pharmacist:false,birthday:'',position:'',newbie_level:'',effective_date:'',notes:'',from_store_id:'',to_store_id:''});
const rows=ref<any[]>([empty()]),selected=ref(0),catalog=ref<any>(null),loading=ref(false),error=ref(''),message=ref(''),issues=ref<any[]>([]),origins=ref<number[]>([]),pending=ref<File|null>(null),removeIndex=ref<number|null>(null),employeeSearch=ref('');
const skippedRows=ref<any[]>([]),transferCount=ref(0),downloading=ref(false),version=ref(''),review=ref(false),receipt=ref<any>(null),submitError=ref('');let requestId='';
const current=computed(()=>rows.value[selected.value]);let baseline=JSON.stringify(rows.value);props.tab.submitOnly=true;
const candidates=computed(()=>employeeSearch.value.trim()?(catalog.value?.employees||[]).filter((e:any)=>[e.employee_code,e.employee_name].join(' ').toLowerCase().includes(employeeSearch.value.trim().toLowerCase())).slice(0,30):[]);
watch(rows,()=>{props.tab.dirty=JSON.stringify(rows.value)!==baseline;issues.value=[];message.value='';version.value='';requestId='';receipt.value=null;},{deep:true,flush:'sync'});
function label(type:string){return catalog.value?.types.find((t:any)=>t.value===type)?.label||type;}
function location(id:string){return catalog.value?.stores.find((s:any)=>s.id===id)?.store_name||catalog.value?.organizationOptions.find((u:any)=>'org:'+u.id===id)?.path||'未選擇';}
function pick(e:any){Object.assign(current.value,{employee_code:e.employee_code,employee_name:e.employee_name,store_id:e.store_id||'',birthday:e.birthday||'',onboarding_is_pharmacist:!!e.is_pharmacist});if(current.value.movement_type==='store_transfer')current.value.from_store_id=e.store_id||'';employeeSearch.value='';}
function typeChanged(){const r=current.value;r.position=r.movement_type==='acting_manager'?'代理店長':'';r.newbie_level='';if(r.movement_type==='store_transfer'){r.from_store_id=r.store_id;r.to_store_id='';}else{r.from_store_id='';r.to_store_id='';}if(r.movement_type!=='onboarding'){r.birthday='';r.onboarding_is_pharmacist=false;if(r.store_id.startsWith('org:'))r.store_id='';}}
async function load(){loading.value=true;error.value='';try{catalog.value=await api('movement-validation');}catch(e){catalog.value=null;error.value=(e as Error).message;}finally{loading.value=false;}}
function add(){if(rows.value.length>=500)return;rows.value.push(empty());origins.value=[];selected.value=rows.value.length-1;}
function remove(){if(removeIndex.value===null)return;rows.value.splice(removeIndex.value,1);if(!rows.value.length)rows.value.push(empty());selected.value=Math.min(selected.value,rows.value.length-1);origins.value=[];removeIndex.value=null;}
function apply(result:any,imported=false){skippedRows.value=result.skipped||[];transferCount.value=result.transferRequests||0;rows.value=result.rows;origins.value=imported?result.sourceRows||[]:[];for(const e of result.errors||[])if(e.field==='onboarding_is_pharmacist'){const i=imported?(result.sourceRows||[]).indexOf(e.row):e.row-1;if(rows.value[i])rows.value[i].onboarding_is_pharmacist=undefined;}issues.value=result.errors||[];selected.value=imported?0:Math.min(selected.value,rows.value.length-1);message.value=result.valid?`${rows.value.length} 筆查核通過，請核對後確認儲存。`:`發現 ${issues.value.length} 個問題，請修正後重新驗證。`;version.value=result.valid&&result.canSubmit?result.version:'';requestId=version.value?crypto.randomUUID():'';}
async function validate(){if(props.tab.busy)return;props.tab.busy=true;error.value='';try{apply(await api('movement-validation',{method:'POST',body:JSON.stringify({rows:rows.value})}));}catch(e){error.value=(e as Error).message;}finally{props.tab.busy=false;}}
async function upload(file:File){pending.value=null;props.tab.busy=true;error.value='';try{const form=new FormData();form.append('file',file);apply(await api('movement-validation',{method:'POST',body:form}),true);}catch(e){error.value=(e as Error).message;}finally{props.tab.busy=false;}}
async function submit(){
 if(props.tab.busy||!version.value||!requestId||receipt.value)return;
 props.tab.busy=true;submitError.value='';
 try{const result=await api('movement-submit',{method:'POST',body:JSON.stringify({rows:rows.value,version:version.value,requestId})});
  receipt.value=result;baseline=JSON.stringify(rows.value);props.tab.dirty=false;review.value=false;message.value=`已儲存 ${result.created} 筆${result.transferRequests?`（其中 ${result.transferRequests} 筆調店為待確認申請，需原店與新店督導都確認才生效，請至「調店登記確認」）`:''}，可至「查看歷史紀錄」核對。${result.skipped?.length?`另有 ${result.skipped.length} 筆已存在且內容完全相同，已自動略過。`:''}`;version.value='';
 }catch(e){submitError.value=(e as Error).message;}finally{props.tab.busy=false;}
}
function nextBatch(){rows.value=[empty()];baseline=JSON.stringify(rows.value);props.tab.dirty=false;selected.value=0;origins.value=[];receipt.value=null;submitError.value='';void load();}
function choose(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file)return;if(props.tab.dirty)pending.value=file;else void upload(file);}
function focusIssue(issue:any){const i=origins.value.length?origins.value.indexOf(issue.row):issue.row-1;if(i>=0)selected.value=i;}
async function download(template=false){if(downloading.value||!catalog.value)return;downloading.value=true;error.value='';const snapshot=JSON.parse(JSON.stringify(rows.value));try{const {movementDraftFile}=await import('../movement-draft-file');const url=URL.createObjectURL(new Blob([movementDraftFile(snapshot,catalog.value,template)],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));const a=document.createElement('a');a.href=url;a.download=template?'人員異動匯入範例.xlsx':'批次異動草稿.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch{error.value='Excel 下載失敗，請重試。';}finally{downloading.value=false;}}
onMounted(load);onBeforeUnmount(()=>{delete props.tab.submitOnly;});
</script>
<template><header class="page-heading"><div><p v-if="!embedded" class="eyebrow">組織與門市 / 人員異動管理</p><h1 v-if="!embedded">批次輸入異動</h1><p>輸入或匯入後先查核，再確認儲存。未儲存內容保留至關閉頁籤。</p></div><button :disabled="loading||tab.busy" @click="load">重新載入選單</button></header>
<p v-if="error" role="alert" class="notice error">{{error}}</p><p v-if="loading" role="status">正在載入門市與員工…</p><p v-if="tab.busy" role="status">正在處理，請稍候…</p><p v-if="message" role="status" class="notice">{{message}}</p>
<p v-if="receipt" class="notice">提交編號：{{receipt.requestId}} <button @click="nextBatch">開始下一批異動</button></p>
<template v-if="catalog"><fieldset :disabled="loading||tab.busy||!!pending||removeIndex!==null||review||!!receipt"><div class="toolbar"><button :disabled="downloading" @click="download(true)">下載匯入範例</button><button :disabled="downloading" @click="download(false)">匯出 Excel</button><label>匯入 Excel<input type="file" accept=".xlsx,.xls" @change="choose"></label><button :disabled="rows.length>=500" @click="add">新增一列</button><button class="primary" @click="validate">驗證 {{rows.length}} 筆異動</button><button v-if="version" class="primary" @click="review=true;submitError=''">核對並儲存 {{rows.length}} 筆</button></div>
<p class="export-hint">匯出 Excel 為目前輸入的批次內容；匯入及驗證不代表已儲存異動。</p><div v-if="skippedRows.length&&!issues.length" role="status" class="notice"><strong>{{skippedRows.length}} 筆已存在且內容完全相同，儲存時自動略過</strong><ul><li v-for="(e,i) in skippedRows" :key="i">{{origins.length?'Excel 第':'第'}} {{e.row}} 列：{{e.message}}</li></ul></div><p v-if="transferCount&&!issues.length" role="status" class="notice">{{transferCount}} 筆調店會建立為待確認申請，需原店與新店督導都確認才生效（系統管理員可代確認）。</p><div v-if="issues.length" role="alert" class="notice error"><strong>{{issues.length}} 個問題</strong><ul><li v-for="(e,i) in issues" :key="i"><button class="issue" @click="focusIssue(e)">{{origins.length?'Excel 第':'第'}} {{e.row}} 列：{{e.message}}</button></li></ul></div>
<div class="draft-layout"><nav aria-label="異動草稿列" class="row-list"><button v-for="(r,i) in rows" :key="i" :aria-current="selected===i?'true':undefined" @click="selected=i;employeeSearch=''">{{i+1}}. {{r.employee_code||'未填員編'}} {{r.employee_name}}<small>{{label(r.movement_type)}} · {{r.effective_date||'未填日期'}}</small></button></nav>
<section class="editor"><div class="row-heading"><h2>第 {{selected+1}} 列<span v-if="origins[selected]"> · Excel 第 {{origins[selected]}} 列</span></h2><button @click="removeIndex=selected">移除此列</button></div>
<label>查找既有員工<input v-model="employeeSearch" placeholder="輸入員編或姓名"></label><div v-if="employeeSearch" class="candidates"><button v-for="e in candidates" :key="e.id" @click="pick(e)">{{e.employee_code}} {{e.employee_name}} · {{location(e.store_id)}}{{e.is_active===false?'（離職）':''}}</button><p v-if="!candidates.length">沒有符合的主檔；新入職人員可直接填寫下方資料。</p><p v-if="candidates.length===30">顯示前 30 筆，請縮小搜尋條件。</p></div>
<div class="fields"><label>員編<input v-model="current.employee_code" maxlength="20"></label><label>姓名<input v-model="current.employee_name" maxlength="100"></label><label>異動類型<select v-model="current.movement_type" aria-label="異動類型" @change="typeChanged"><option v-for="t in catalog.types" :key="t.value" :value="t.value">{{t.label}}</option></select></label><label>生效日期<input v-model="current.effective_date" type="date" min="1912-01-01"></label>
<template v-if="current.movement_type==='store_transfer'"><label>原任職門市<select v-model="current.from_store_id" aria-label="原任職門市"><option value="">請選擇</option><option v-for="s in catalog.stores" :key="s.id" :value="s.id">{{s.store_code}} {{s.store_name}}</option></select></label><label>新任職門市<select v-model="current.to_store_id" aria-label="新任職門市"><option value="">請選擇</option><option v-for="s in catalog.stores" :key="s.id" :value="s.id">{{s.store_code}} {{s.store_name}}</option></select></label></template>
<label v-else class="wide">任職門市／組織<select v-model="current.store_id" aria-label="任職門市／組織"><option value="">請選擇</option><optgroup label="門市"><option v-for="s in catalog.stores" :key="s.id" :value="s.id">{{s.store_code}} {{s.store_name}}</option></optgroup><optgroup v-if="current.movement_type==='onboarding'" label="總部最下層單位"><option v-for="u in catalog.organizationOptions" :key="u.id" :value="'org:'+u.id">{{u.code}} {{u.path}}</option></optgroup></select><small v-if="current.movement_type==='return_to_work'" data-testid="return-store-hint">復職不一定回原店：預設為員工目前的任職門市，可改選復職門市；復職當月起列入該門市名冊。</small></label>
<template v-if="current.movement_type==='onboarding'"><label>生日<input v-model="current.birthday" type="date" min="1900-01-01"></label><label>入職是否為藥師<select v-model="current.onboarding_is_pharmacist" aria-label="入職是否為藥師"><option :value="undefined">請確認</option><option :value="false">否</option><option :value="true">是</option></select></label></template>
<template v-if="current.movement_type==='promotion'"><label>升任後職位<select v-model="current.position" aria-label="升任後職位" @change="current.newbie_level=''"><option value="">請選擇</option><option v-for="p in catalog.positions" :key="p">{{p}}</option></select></label><label v-if="['新人','行政'].includes(current.position)">新人／行政階級<select v-model="current.newbie_level" aria-label="新人／行政階級"><option value="">請選擇</option><option v-for="level in current.position==='新人'?catalog.newbieLevels:catalog.adminLevels" :key="level.value" :value="level.value">{{level.label}}</option></select></label></template><p v-if="current.movement_type==='acting_manager'">代理職位：代理店長</p>
<label class="wide">備註<textarea v-model="current.notes" maxlength="5000" rows="4"></textarea></label></div></section></div></fieldset></template>
<Modal v-if="review" title="確認儲存批次異動" :busy="tab.busy" wide @cancel="review=false">
<p>共 {{rows.length}} 筆，依生效日期、同日列序處理。儲存會寫入異動歷程並同步主檔及相關月資料，任一列失敗皆不儲存。</p>
<p>未來日期：升職依既有排程生效；其他異動會在儲存後立即更新主檔，並記錄指定生效日。</p>
<div class="review-table"><table><thead><tr><th>列</th><th>員工</th><th>異動</th><th>生效日</th><th>任職門市／組織</th></tr></thead><tbody><tr v-for="(r,i) in rows" :key="i"><td data-label="列">{{i+1}}</td><td data-label="員工">{{r.employee_code}} {{r.employee_name}}</td><td data-label="異動">{{label(r.movement_type)}}<small v-if="r.position">{{r.position}} {{r.newbie_level}}</small></td><td data-label="生效日">{{r.effective_date}}</td><td data-label="門市／組織">{{r.movement_type==='store_transfer'?location(r.from_store_id)+' → '+location(r.to_store_id):location(r.store_id)}}</td></tr></tbody></table></div>
<p v-if="submitError" role="alert" class="notice error">{{submitError}}</p>
<div class="dialog-actions"><button :disabled="tab.busy" @click="review=false">返回草稿</button><button class="primary" :disabled="tab.busy" @click="submit">{{tab.busy?'正在儲存…':submitError?'重試儲存':'確認儲存 '+rows.length+' 筆'}}</button></div>
</Modal>
<Modal v-if="pending" title="取代目前異動草稿" @cancel="pending=null"><p>成功解析 {{pending.name}} 後，將取代目前 {{rows.length}} 筆草稿。</p><div class="dialog-actions"><button @click="pending=null">保留目前內容</button><button class="primary" @click="upload(pending!)">載入新檔案</button></div></Modal>
<Modal v-if="removeIndex!==null" title="移除異動草稿列" @cancel="removeIndex=null"><p>移除第 {{removeIndex+1}} 列 {{rows[removeIndex]?.employee_name}} 的草稿？</p><div class="dialog-actions"><button @click="removeIndex=null">保留</button><button @click="remove">確認移除</button></div></Modal>
</template>
<style scoped>.review-table{max-height:45vh;overflow:auto}.review-table table{width:100%;min-width:600px}.review-table th,.review-table td{text-align:left;padding:12px;border-bottom:1px solid var(--line)}fieldset{border:0;padding:0;min-width:0}.toolbar,.row-heading{display:flex;gap:16px;align-items:center;justify-content:space-between;flex-wrap:wrap;margin:24px 0}.toolbar label{margin-right:auto}.draft-layout{display:grid;grid-template-columns:250px minmax(0,1fr);gap:28px}.row-list{max-height:650px;overflow:auto;border-right:1px solid var(--line);padding-right:12px}.row-list button{display:block;width:100%;text-align:left;margin-bottom:8px;white-space:normal;overflow-wrap:anywhere}.row-list [aria-current]{border-color:var(--primary);background:var(--surface)}small{display:block;margin-top:6px;color:var(--muted)}h2{font-size:18px;margin:0}.row-heading{margin-top:0}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin-top:20px}label{display:grid;gap:8px}input,select,textarea{width:100%;min-width:0}.wide{grid-column:1/-1}.candidates{max-height:240px;overflow:auto}.candidates button{display:block;width:100%;text-align:left;white-space:normal;margin-top:6px}.notice ul{max-height:240px;overflow:auto}.issue{text-align:left;white-space:normal;border:0;background:transparent;text-decoration:underline}@media(max-width:750px){.review-table table{min-width:0}.review-table thead{display:none}.review-table tr{display:block;border-bottom:1px solid var(--line);padding:8px 0}.review-table td{display:block;padding:6px 0;border:0;overflow-wrap:anywhere}.review-table td::before{content:attr(data-label);display:inline-block;min-width:85px;color:var(--muted)}.draft-layout{grid-template-columns:1fr}.row-list{max-height:180px;border-right:0;border-bottom:1px solid var(--line);padding:0 0 12px}.fields{grid-template-columns:1fr}}</style>
